function F({registerIndicator:f,sma:p,nulls:y}){f({id:"oa-rsv",name:"Rogers-Satchell Volatility (RSV)",category:"Volatility",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:20,min:1,max:5e3,step:1,tooltip:"Lookback period for SMA smoothing of the Rogers-Satchell variance."},{key:"annualize",type:"boolean",label:"Annualize Volatility",default:!0,tooltip:"Scale the output to an annual figure."},{key:"annualPeriods",type:"number",label:"Annual Periods",default:252,min:1,max:1e5,step:1,tooltip:"Number of periods in a year (252 for daily, 52 for weekly)."}],plots:[{key:"rsv",type:"line",title:"RSV",style:{color:"#ffeb3b",lineWidth:2}}],calc(l,n){const b=Math.max(1,Math.floor(Number(n.length)||20)),M=n.annualize!==!1,d=Math.max(1,Math.floor(Number(n.annualPeriods)||252)),a=l.length,o=1e-7,i=new Array(a).fill(NaN);for(let t=0;t<a;t++){const e=l[t],c=Math.max(Number.isFinite(e.high)?e.high:0,o),h=Math.max(Number.isFinite(e.low)?e.low:0,o),u=Math.max(Number.isFinite(e.open)?e.open:0,o),m=Math.max(Number.isFinite(e.close)?e.close:0,o),N=Math.log(c/u),x=Math.log(c/m),k=Math.log(h/u),v=Math.log(h/m);i[t]=N*x+k*v}const r=p(i,b),g=M?Math.sqrt(d):1,s=new Array(a).fill(NaN);for(let t=0;t<a;t++)Number.isFinite(r[t])&&(s[t]=Math.sqrt(Math.max(0,r[t]))*g);return{rsv:y(s)}}})}export{F as default};
